public void Write(byte[] b, int off, int len)
{
    while (len > 0)
    {
        int n = Math.Min(len, BYTES_TO_WRITE_BEFORE_CANCEL_CHECK);
        count += n;
        if (checkCancelAt <= count)
        {
            if (writeMonitor.IsCancelled())
            {
                throw new IOException(JGitText.Get().PackingCancelledDuringObjectsWriting);
            }
            checkCancelAt = count + BYTES_TO_WRITE_BEFORE_CANCEL_CHECK;
        }
        @out.Write(b, off, n);
        md.Update(b, off, n);
        off += n;
        len -= n;
    }
}

public static Transport Open(URIish uri)
{
    foreach (WeakReference<TransportProtocol> weakRef in protocols)
    {
        TransportProtocol proto;
        if (!weakRef.TryGetTarget(out proto) || proto == null)
        {
            protocols.Remove(weakRef);
            continue;
        }

        if (proto.CanHandle(uri, null, null))
            return proto.Open(uri);
    }

    throw new NotSupportedException(
        string.Format(JGitText.Get().URINotSupported, uri));
}

