public string GetText(Interval interval)
{
    int start = interval.a;
    int stop   = interval.b;

    if (start < 0 || stop < 0)
        return "";

    Fill();

    if (stop >= tokens.Count)
        stop = tokens.Count - 1;

    var sb = new StringBuilder();

    for (int i = start; i <= stop; i++)
    {
        Token t = tokens[i];
        if (t.GetType() == Token.EOF)
            break;

        sb.Append(t.GetText());
    }

    return sb.ToString();
}

