public void Decode(byte[] blocks, int blocksOffset, long[] values, int valuesOffset, int iterations)
{
    for (int i = 0; i < iterations; ++i)
    {
        long byte0 = blocks[blocksOffset++] & 0xFFL;
        long byte1 = blocks[blocksOffset++] & 0xFFL;
        values[valuesOffset++] = (byte0 << 2) | (byte1 >> 6);

        long byte2 = blocks[blocksOffset++] & 0xFFL;
        values[valuesOffset++] = ((byte1 & 63L) << 4) | (byte2 >> 4);

        long byte3 = blocks[blocksOffset++] & 0xFFL;
        values[valuesOffset++] = ((byte2 & 15L) << 6) | (byte3 >> 2);

        long byte4 = blocks[blocksOffset++] & 0xFFL;
        values[valuesOffset++] = ((byte3 & 3L) << 8) | byte4;
    }
}

