public static IndexWriterConfig CreateWriterConfig(Config config, PerfRunData runData,
                                                  OpenMode mode, IndexCommit commit)
{
    var iwConf = new IndexWriterConfig(runData.Analyzer);
    iwConf.SetOpenMode(mode);

    IndexDeletionPolicy indexDeletionPolicy = GetIndexDeletionPolicy(config);
    iwConf.SetIndexDeletionPolicy(indexDeletionPolicy);

    if (commit != null)
    {
        iwConf.SetIndexCommit(commit);
    }

    string mergeScheduler = config.Get("merge.scheduler",
                                       "org.apache.lucene.index.ConcurrentMergeScheduler");

    if (mergeScheduler.Equals(typeof(NoMergeScheduler).FullName))
    {
        iwConf.SetMergeScheduler(NoMergeScheduler.Instance);
    }
    else
    {
        try
        {
            var type = Type.GetType(mergeScheduler);
            if (type != null)
            {
                iwConf.SetMergeScheduler((MergeScheduler)Activator.CreateInstance(type));
            }
        }
        catch (Exception)
        {
            // ignore
        }
    }

    return iwConf;
}

public string Validate(string uri, int start, int end, string name)
{
    for (int i = start; i < end; )
    {
        char ch = uri[i];
        if ((ch >= 'a' && ch <= 'z') ||
            (ch >= 'A' && ch <= 'Z') ||
            (ch >= '0' && ch <= '9') ||
            isRetained(ch))
        {
            i++;
        }
        else if (ch == '%')
        {
            if (i + 2 >= end)
            {
                throw new UriFormatException($"Incomplete % sequence in {name} at index {i}");
            }

            int d1 = hexToInt(uri[i + 1]);
            int d2 = hexToInt(uri[i + 2]);

            if (d1 == -1 || d2 == -1)
            {
                throw new UriFormatException($"Invalid % sequence: {uri.Substring(i, 3)} in {name} at index {i}");
            }

            i += 3;
        }
        else
        {
            throw new UriFormatException($"Illegal character in {name} at index {i}");
        }
    }

    return uri.Substring(start, end - start);
}

public long Skip(long byteCount)
{
    if (byteCount < 0)
        throw new ArgumentException("byteCount < 0: " + byteCount);

    lock (@lock)
    {
        CheckNotClosed();

        if (byteCount < 1)
            return 0;

        if (end - pos >= byteCount)
        {
            pos += byteCount;
            return byteCount;
        }

        long read = end - pos;
        pos = end;

        while (read < byteCount)
        {
            if (FillBuf() == -1)
                return read;

            if (end - pos >= byteCount - read)
            {
                pos += byteCount - read;
                return byteCount;
            }

            read += (end - pos);
            pos = end;
        }

        return byteCount;
    }
}

public CharsetEncoder ReplaceWith(byte[] replacement)
{
    if (replacement == null)
    {
        throw new ArgumentException("replacement == null");
    }
    if (replacement.Length == 0)
    {
        throw new ArgumentException("replacement.length == 0");
    }
    if (replacement.Length > maxBytesPerChar())
    {
        throw new ArgumentException("replacement length > maxBytesPerChar: " + replacement.Length + " > " + maxBytesPerChar());
    }
    if (!isLegalReplacement(replacement))
    {
        throw new ArgumentException("bad replacement: [" + string.Join(", ", replacement) + "]");
    }
    this.replacementBytes = replacement;
    implReplaceWith(replacementBytes);
    return this;
}

