public static string htmlEncode(string plainText)
{
    if (plainText == null || plainText.Length == 0)
    {
        return "";
    }

    var result = new System.Text.StringBuilder(plainText.Length);
    for (int index = 0; index < plainText.Length; index++)
    {
        char ch = plainText[index];
        switch (ch)
        {
            case '\"':
                result.Append("&quot;");
                break;
            case '&':
                result.Append("&amp;");
                break;
            case '<':
                result.Append("&lt;");
                break;
            case '>':
                result.Append("&gt;");
                break;
            case '\'':
                result.Append("&#x27;");
                break;
            case '/':
                result.Append("&#x2F;");
                break;
            default:
                result.Append(ch);
                break;
        }
    }
    return result.ToString();
}

