public IList<string> Call()
{
    CheckCallable();
    IList<string> result = new List<string>();
    if (tags.Count == 0)
        return result;

    try
    {
        SetCallable(false);
        foreach (string tagName in tags)
        {
            if (tagName == null)
                continue;

            Ref currentRef = repo.FindRef(tagName);
            if (currentRef == null)
                continue;

            string fullName = currentRef.Name;
            RefUpdate update = repo.UpdateRef(fullName);
            update.ForceUpdate = true;
            Result deleteResult = update.Delete();

            bool ok = true;
            switch (deleteResult)
            {
                case Result.IO_FAILURE:
                case Result.LOCK_FAILURE:
                case Result.REJECTED:
                    ok = false;
                    break;
                default:
                    break;
            }

            if (ok)
            {
                result.Add(fullName);
            }
            else
            {
                throw new JGitInternalException(
                    string.Format(JGitText.Get().DeleteTagUnexpectedResult, deleteResult.ToString()));
            }
        }

        return result;
    }
    catch (IOException ioe)
    {
        throw new JGitInternalException(ioe.Message, ioe);
    }
}

