public LongsRef Next(int count)
{
    Debug.Assert(nextValues.length >= 0);
    Debug.Assert(count > 0);
    Debug.Assert(nextValues.offset + nextValues.length <= nextValues.longs.Length);

    nextValues.offset += nextValues.length;
    int remaining = valueCount - position - 1;

    if (remaining <= 0)
    {
        throw new EndOfStreamException();
    }

    count = Math.Min(remaining, count);

    if (nextValues.offset == nextValues.longs.Length)
    {
        long remainingBlocks = format.byteCount(packedIntsVersion, remaining, bitsPerValue);
        int blocksToRead = (int)Math.Min(remainingBlocks, nextBlocks.Length);

        in.readBytes(nextBlocks, 0, blocksToRead);

        if (blocksToRead < nextBlocks.Length)
        {
            Array.Fill(nextBlocks, (byte)0, blocksToRead, nextBlocks.Length - blocksToRead);
        }

        bulkOperation.decode(nextBlocks, 0, nextValues.longs, 0, iterations);
        nextValues.offset = 0;
    }

    nextValues.length = Math.Min(nextValues.longs.Length - nextValues.offset, count);
    position += nextValues.length;
    return nextValues;
}

public void Reset(bool zeroFillBuffers, bool reuseFirst)
{
    if (bufferUpto != -1)
    {
        if (zeroFillBuffers)
        {
            for (int i = 0; i < bufferUpto; i++)
            {
                Array.Fill(buffers[i], 0);
            }
            Array.Fill(buffers[bufferUpto], 0, 0, intUpto);
        }

        if (bufferUpto > 0 || !reuseFirst)
        {
            int offset = reuseFirst ? 1 : 0;
            allocator.RecycleIntBlocks(buffers, offset, 1 + bufferUpto);
            Array.Fill(buffers, null, offset, (bufferUpto + 1) - offset);
        }

        if (reuseFirst)
        {
            bufferUpto = 0;
            intUpto = 0;
            intOffset = 0;
            buffer = buffers[0];
        }
        else
        {
            bufferUpto = -1;
            intUpto = INT_BLOCK_SIZE;
            intOffset = -INT_BLOCK_SIZE;
            buffer = null;
        }
    }
}

using System.Diagnostics;

public static QualityStats Average(QualityStats[] stats)
{
    QualityStats avg = new QualityStats(0, 0);
    if (stats.Length == 0)
    {
        return avg;
    }

    int m = 0;
    for (int i = 0; i < stats.Length; i++)
    {
        avg.searchTime += stats[i].searchTime;
        avg.docNamesExtractTime += stats[i].docNamesExtractTime;

        if (stats[i].maxGoodPoints > 0)
        {
            m++;
            avg.numGoodPoints += stats[i].numGoodPoints;
            avg.numPoints += stats[i].numPoints;
            avg.pReleventSum += stats[i].GetAvp();
            avg.recall += stats[i].recall;
            avg.mrr += stats[i].GetMRR();
            avg.maxGoodPoints += stats[i].maxGoodPoints;

            for (int j = 1; j < avg.pAt.Length; j++)
            {
                avg.pAt[j] += stats[i].GetPrecisionAt(j);
            }
        }
    }

    Debug.Assert(m > 0, "Fishy: no \"good\" queries!");

    avg.searchTime /= stats.Length;
    avg.docNamesExtractTime /= stats.Length;
    avg.numGoodPoints /= m;
    avg.numPoints /= m;
    avg.recall /= m;
    avg.mrr /= m;
    avg.maxGoodPoints /= m;

    for (int j = 1; j < avg.pAt.Length; j++)
    {
        avg.pAt[j] /= m;
    }

    avg.pReleventSum /= m;
    avg.pReleventSum *= avg.maxGoodPoints;

    return avg;
}

