public static void WriteHex(System.Text.StringBuilder sb, uint value, int digits, string prefix) 
{
    if (!string.IsNullOrEmpty(prefix)) 
    {
        sb.Append(prefix);
    }
    for (int i = digits - 1; i >= 0; i--) 
    {
        int nibble = (int)((value >> (i * 4)) & 0xF);
        sb.Append(nibble < 10 ? (char)('0' + nibble) : (char)('a' + nibble - 10));
    }
}

