public static int Update(int hash, int value)
{
    const int c1 = 0xCC9E2D51;
    const int c2 = 0x1B873593;
    const int r1 = 15;
    const int r2 = 13;
    const int m = 5;
    const int n = 0xE6546B64;
    int k = value;
    k = k * c1;
    k = (k << r1) | (k >> (32 - r1));
    k = k * c2;
    hash = hash ^ k;
    hash = (hash << r2) | (hash >> (32 - r2));
    hash = hash * m + n;
    return hash;
}

