public FileMode GetIndexFileMode(DirCacheIterator indexIter)
{
    var wtMode = GetEntryFileMode();
    if (indexIter == null)
    {
        return wtMode;
    }
    var iMode = indexIter.GetEntryFileMode();
    if (GetOptions().IsFileMode && iMode != FileMode.GitLink && iMode != FileMode.Tree)
    {
        return wtMode;
    }
    if (!GetOptions().IsFileMode)
    {
        if (wtMode == FileMode.RegularFile && iMode == FileMode.ExecutableFile)
        {
            return iMode;
        }
        if (wtMode == FileMode.ExecutableFile && iMode == FileMode.RegularFile)
        {
            return iMode;
