    if (iMode == FileMode.GitLink && wtMode == FileMode.Tree && !GetOptions().IsDirNoGitLinks)
    {
        return iMode;
    }
    if (iMode == FileMode.Tree && wtMode == FileMode.GitLink)
    {
        return iMode;
    }
    return wtMode;
}

public DoubleRange(string label, double minIn, bool minInclusive, double maxIn, bool maxInclusive) 
    : base(label)
{
    if (double.IsNaN(minIn))
    {
        throw new ArgumentException("min cannot be NaN");
    }
    if (!minInclusive)
    {
        minIn = Math.NextAfter(minIn, double.PositiveInfinity);
    }
    if (double.IsNaN(maxIn))
    {
        throw new ArgumentException("max cannot be NaN");
    }
    if (!maxInclusive)
    {
        maxIn = Math.NextAfter(maxIn, double.NegativeInfinity);
    }
    if (minIn > maxIn)
    {
        FailNoMatch();
    }
    this.min = minIn;
    this.max = maxIn;
}

public string GetText(Interval interval) 
{
    if (interval.A < 0 || interval.B < interval.A - 1) 
    {
        throw new ArgumentException("invalid interval");
    }
    int bufferStartIndex = GetBufferStartIndex();
    if (n > 0 && data[n - 1] == char.MaxValue) 
    {
        if (interval.A + interval.Length() > bufferStartIndex + n) 
        {
            throw new ArgumentException("the interval extends past the end of the stream");
        }
    }
    if (interval.A < bufferStartIndex || interval.B >= bufferStartIndex + n) 
    {
        throw new NotSupportedException("interval " + interval + " outside buffer: " + bufferStartIndex + ".." + (bufferStartIndex + n - 1));
    }
    int i = interval.A - bufferStartIndex;
    return new string(data, i, interval.Length());
}

