public static int Tagger(byte[] b, int ptr) 
{
    int sz = b.Length;
    if (ptr == 0) 
        ptr += 48;
    while (ptr < sz) 
    {
        if (b[ptr] == '\n') 
            return -1;
        int m = Match(b, ptr, Tagger);
        if (m >= 0) 
            return m;
        ptr = NextLF(b, ptr);
    }
    return -1;
}

