}

public SmallDocSet Union(SmallDocSet other) 
{
    SmallDocSet bigger;
    SmallDocSet smaller;
    if (other.intSet.size() > this.intSet.size()) 
    {
        bigger = other;
        smaller = this;
    } 
    else 
    {
        bigger = this;
        smaller = other;
    }
    foreach (int v in smaller.intSet.keys) 
    {
        if (v == smaller.intSet.emptyVal)
            continue;
        bigger.Set(v);
    }
    return bigger;
}

