public static Ptg CreatePtg(LittleEndianInput in1) 
{
    byte id = in1.ReadByte();
    if (id < 0x20) 
    {
        return CreateBasePtg(id, in1);
    }
    Ptg retval = CreateClassifiedPtg(id, in1);
    if (id >= 0x60) 
    {
        retval.SetClass(Class.Array);
    } 
    else if (id >= 0x40) 
    {
        retval.SetClass(Class.Value);
    } 
    else 
    {
        retval.SetClass(Class.Reference);
    }
    return retval;
}

