public void Insert(int index, T element) 
{
    if (index == Count) 
    {
        Add(element);
    } 
    else if (index < 0 || Count < index) 
    {
        throw new IndexOutOfRangeException(index.ToString());
    } 
    else 
    {
        Add(default(T)); 
        for (int oldIdx = Count - 2; index <= oldIdx; oldIdx--) 
        {
            this[oldIdx + 1] = this[oldIdx];
        }
        this[index] = element;
    }
}

