public void Write(byte[] b, int off, int len)
{
    while (0 < len)
    {
        int n = Math.Min(len, BYTES_TO_WRITE_BEFORE_CANCEL_CHECK);
        count += n;
        if (checkCancelAt <= count)
        {
            if (writeMonitor.IsCanceled)
            {
                throw new IOException(JGitText.Instance.PackingCancelledDuringObjectsWriting);
            }
            checkCancelAt = count + BYTES_TO_WRITE_BEFORE_CANCEL_CHECK;
        }
        out.Write(b, off, n);
        md.Update(b, off, n);
        off += n;
        len -= n;
    }
}

