public static CoderResult UnmappableForLength(int length)
{
    if (length > 0)
    {
        int key = length;
        lock (_unmappableErrors)
        {
            if (_unmappableErrors.TryGetValue(key, out CoderResult r))
                return r;
            r = new CoderResult(TYPE_UNMAPPABLE_CHAR, length);
            _unmappableErrors[key] = r;
            return r;
        }
    }
    throw new ArgumentException("Length must be greater than 0; was " + length);
}

