public string GetText(Interval interval) 
{
    int start = interval.a;
    int stop = interval.b;
    if (start < 0 || stop < 0) return "";
    Fill();
    if (stop >= Tokens.Count) stop = Tokens.Count - 1;
    StringBuilder buf = new StringBuilder();
    for (int i = start; i <= stop; i++) 
    {
        Token t = Tokens[i];
        if (t.Type == Token.EOF) break;
        buf.Append(t.Text);
    }
    return buf.ToString();
}

public static int Update(int hash, int value) 
{
    const int c1 = 0xCC9E2D51;
    const int c2 = 0x1B873593;
    const int r1 = 15;
    const int r2 = 13;
    const int m = 5;
    const int n = 0xE6546B64;
    int k = value;
    k = k * c1;
    k = (k << r1) | (k >>> (32 - r1));
    k = k * c2;
    hash = hash ^ k;
    hash = (hash << r2) | (hash >>> (32 - r2));
    hash = hash * m + n;
    return hash;
}

