public static Boolean? CoerceValueToBoolean(ValueEval ve, bool stringsAreBlanks)
{
    if (ve == null || ve == BlankEval.Instance)
    {
        return null;
    }
    if (ve is BoolEval)
    {
        return ((BoolEval)ve).BooleanValue;
    }
    if (ve is StringEval)
    {
        if (stringsAreBlanks)
        {
            return null;
        }
        String str = ((StringEval)ve).StringValue;
        if (str.Equals("true", StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }
        if (str.Equals("false", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }
        throw new EvaluationException(ErrorEval.VALUE_INVALID);
    }
    if (ve is NumericValueEval)
    {
        NumericValueEval ne = (NumericValueEval)ve;
        double d = ne.NumberValue;
        if (double.IsNaN(d))
        {
            throw new EvaluationException(ErrorEval.VALUE_INVALID);
        }
        return d != 0;
    }
    if (ve is ErrorEval)
    {
        throw new EvaluationException((ErrorEval)ve);
    }
    throw new Exception("Unexpected eval (" + ve.GetType().Name + ")");
}

public void Reset(bool zeroFillBuffers, bool reuseFirst)
{
    if (bufferUpto != -1)
    {
        if (zeroFillBuffers)
        {
            for (int i = 0; i < bufferUpto; i++)
            {
                Array.Clear(buffers[i], 0, buffers[i].Length);
            }
            Array.Clear(buffers[bufferUpto], 0, intUpto);
        }
        if (bufferUpto > 0 || !reuseFirst)
        {
            int offset = reuseFirst ? 1 : 0;
            allocator.RecycleIntBlocks(buffers, offset, 1 + bufferUpto);
            Array.Clear(buffers, offset, bufferUpto + 1 - offset);
        }
        if (reuseFirst)
        {
            bufferUpto = 0;
            intUpto = 0;
            intOffset = 0;
            buffer = buffers[0];
        }
        else
        {
            bufferUpto = -1;
            intUpto = INT_BLOCK_SIZE;
            intOffset = -INT_BLOCK_SIZE;
            buffer = null;
        }
    }
}

