public long Skip(long byteCount)
{
    if (byteCount < 0)
    {
        throw new ArgumentException("byteCount < 0: " + byteCount);
    }
    lock (lockObj)
    {
        CheckNotClosed();
        if (byteCount < 1)
        {
            return 0;
        }
        if (end - pos >= byteCount)
        {
            pos += byteCount;
            return byteCount;
        }
        long read = end - pos;
        pos = end;
        while (read < byteCount)
        {
            if (FillBuf() == -1)
            {
                return read;
            }
            if (end - pos >= byteCount - read)
            {
                pos += byteCount - read;
                return byteCount;
            }
            read += (end - pos);
            pos = end;
        }
        return byteCount;
    }
}

public string Validate(string uri, int start, int end, string name)
{
    for (int i = start; i < end;)
    {
        char ch = uri[i];
        if ((ch >= 'a' && ch <= 'z') ||
            (ch >= 'A' && ch <= 'Z') ||
            (ch >= '0' && ch <= '9') ||
            IsRetained(ch))
        {
            i++;
        }
        else if (ch == '%')
        {
            if (i + 2 >= end)
            {
                throw new UriFormatException($"Incomplete % sequence in {name} at index {i}");
            }
            int d1 = HexToInt(uri[i + 1]);
            int d2 = HexToInt(uri[i + 2]);
            if (d1 == -1 || d2 == -1)
            {
                throw new UriFormatException($"Invalid % sequence: {uri.Substring(i, 3)} in {name} at index {i}");
            }
            i += 3;
        }
        else
        {
            throw new UriFormatException($"Illegal character in {name} at index {i}");
        }
    }
    return uri.Substring(start, end - start);
}

public EncoderReplacementFallback ReplaceWith(byte[] replacement) 
{
