    if (replacement.Length > GetMaxByteCount(1))
        throw new ArgumentException("replacement length > maxBytesPerChar: " + replacement.Length + " > " + GetMaxByteCount(1));
    if (!IsValidReplacement(replacement))
        throw new ArgumentException("bad replacement: " + BitConverter.ToString(replacement));
    this._replacement = replacement;
    return this;
}

public static string HtmlEncode(string plainText)
{
    if (string.IsNullOrEmpty(plainText))
    {
        return "";
    }
    var result = new System.Text.StringBuilder(plainText.Length);
    foreach (var ch in plainText)
    {
        switch (ch)
        {
            case '"':
                result.Append("&quot;");
                break;
            case '&':
                result.Append("&amp;");
                break;
            case '<':
                result.Append("&lt;");
                break;
            case '>':
                result.Append("&gt;");
                break;
            case '\'':
                result.Append("&#x27;");
                break;
            case '/':
                result.Append("&#x2F;");
                break;
            default:
                result.Append(ch);
                break;
        }
    }
    return result.ToString();
}

public List<string> Call() {
    CheckCallable();
    var result = new List<string>();
    if (!tags.Any())
        return result;
    try {
        SetCallable(false);
        foreach (var tagName in tags) {
            if (tagName == null)
                continue;
            var currentRef = repo.FindRef(tagName);
            if (currentRef == null)
                continue;
            var fullName = currentRef.Name;
            var update = repo.UpdateRef(fullName);
            update.ForceUpdate = true;
            var deleteResult = update.Delete();
            var ok = true;
            switch (deleteResult) {
                case RefUpdate.Result.IOFailure:
                case RefUpdate.Result.LockFailure:
                case RefUpdate.Result.Rejected:
                    ok = false;
                    break;
            }
            if (ok)
                result.Add(fullName);
            else
                throw new GitInternalException(string.Format("Unexpected result when deleting tag: {0}", deleteResult));
        }
        return result;
    } catch (IOException ioe) {
        throw new GitInternalException(ioe.Message, ioe);
    }
}

