    sb.Append("    .xfindex   = ").Append(HexDump.ShortToHex(GetXFIndex())).Append("\n");
    sb.Append("    .string_len= ").Append(HexDump.ShortToHex(_field4StringLen)).Append("\n");
    sb.Append("    .unicode_flag= ").Append(HexDump.ByteToHex(_field5UnicodeFlag)).Append("\n");
