public void write(byte[] b, int off, int len) throws IOException {
    if ((off < 0) || (off > b.length) || (len < 0) || ((off + len) > b.length) || ((off + len) < 0)) {
        throw new IndexOutOfBoundsException();
    } else if (len == 0) {
        return;
    }
    do {
        createBlockIfNeeded();
        int writeBytes = Math.min(buffer.remaining(), len);
        buffer.put(b, off, writeBytes);
        off += writeBytes;
        len -= writeBytes;
    } while (len > 0);
}

public override void write(byte[] b, int off, int len)
{
    while (0 < len)
    {
        int n = Math.Min(len, BYTES_TO_WRITE_BEFORE_CANCEL_CHECK);
        count += n;
        if (checkCancelAt <= count)
        {
            if (writeMonitor.IsCancelled())
            {
                throw new IOException(JGitText.get().packingCancelledDuringObjectsWriting);
            }
            checkCancelAt = count + BYTES_TO_WRITE_BEFORE_CANCEL_CHECK;
        }
        out.write(b, off, n);
        md.update(b, off, n);
        off += n;
        len -= n;
    }
}

