    maxSubwordSize = GetInt(args, "maxSubwordSize", CompoundWordTokenFilterBase.DEFAULT_MAX_SUBWORD_SIZE);
    onlyLongestMatch = GetBoolean(args, "onlyLongestMatch", true);
    if (args.Count > 0)
    {
        throw new ArgumentException("Unknown parameters: " + args);
    }
}

public static IndexWriterConfig createWriterConfig(Config config, PerfRunData runData, OpenMode mode, IndexCommit commit) {
    IndexWriterConfig iwConf = new IndexWriterConfig(runData.getAnalyzer());
    iwConf.setOpenMode(mode);
    IndexDeletionPolicy indexDeletionPolicy = getIndexDeletionPolicy(config);
    iwConf.setIndexDeletionPolicy(indexDeletionPolicy);
    if (commit != null) {
        iwConf.setIndexCommit(commit);
    }
    String mergeScheduler = config.get("merge.scheduler", "org.apache.lucene.index.ConcurrentMergeScheduler");
    if (mergeScheduler.equals(NoMergeScheduler.class.getName())) {
        iwConf.setMergeScheduler(NoMergeScheduler.INSTANCE);
    } else {
        try {
            iwConf.setMergeScheduler(Class.forName(mergeScheduler).asSubclass(typeof(MergeScheduler)).getConstructor().newInstance());
        } catch (Exception e) {
        }
    }
}

public static bool? coerceValueToBoolean(ValueEval ve, bool stringsAreBlanks)
{
    if (ve == null || ve == BlankEval.instance)
    {
        return null;
    }
    if (ve is BoolEval)
    {
        return ((BoolEval)ve).getBooleanValue();
    }
    if (ve is StringEval)
    {
        if (stringsAreBlanks)
        {
            return null;
        }
        string str = ((StringEval)ve).getStringValue();
        if (string.Equals(str, "true", StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }
        if (string.Equals(str, "false", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }
        throw new EvaluationException(ErrorEval.VALUE_INVALID);
    }
    if (ve is NumericValueEval)
    {
        NumericValueEval ne = (NumericValueEval)ve;
        double d = ne.getNumberValue();
        if (double.IsNaN(d))
        {
            throw new EvaluationException(ErrorEval.VALUE_INVALID);
        }
        return d != 0;
    }
    if (ve is ErrorEval)
    {
        throw new EvaluationException((ErrorEval)ve);
    }
    throw new RuntimeException("Unexpected eval (" + ve.GetType().Name + ")");
}

public int FillFields(byte[] data, int offset, EscherRecordFactory recordFactory)
{
    int bytesRemaining = ReadHeader(data, offset);
    int pos = offset + 8;
    int size = 0;
    field_1_color1 = LittleEndian.GetInt(data, pos + size);
    size += 4;
    field_2_color2 = LittleEndian.GetInt(data, pos + size);
    size += 4;
    field_3_color3 = LittleEndian.GetInt(data, pos + size);
    size += 4;
    field_4_color4 = LittleEndian.GetInt(data, pos + size);
    size += 4;
    bytesRemaining -= size;
    if (bytesRemaining != 0)
    {
        throw new RecordFormatException("Expecting no remaining data but got " + bytesRemaining + " byte(s).");
    }
    return 8 + size + bytesRemaining;
}

public LongsRef next(int count) throws IOException {
    assert nextValues.length >= 0;
    assert count > 0;
    assert nextValues.offset + nextValues.length <= nextValues.longs.length;
    nextValues.offset += nextValues.length;
    final int remaining = valueCount - position - 1;
    if (remaining <= 0) {
        throw new EOFException();
    }
    count = Math.min(remaining, count);
    if (nextValues.offset == nextValues.longs.length) {
        final long remainingBlocks = format.byteCount(packedIntsVersion, remaining, bitsPerValue);
        final int blocksToRead = (int) Math.min(remainingBlocks, nextBlocks.length);
        in.readBytes(nextBlocks, 0, blocksToRead);
        if (blocksToRead < nextBlocks.length) {
            Arrays.fill(nextBlocks, blocksToRead, nextBlocks.length, (byte) 0);
        }
        bulkOperation.decode(nextBlocks, 0, nextValues.longs, 0, iterations);
        nextValues.offset = 0;
    }
    nextValues.length = Math.min(nextValues.longs.length - nextValues.offset, count);
    position += nextValues.length;
    return nextValues;
}

public static void registerFunction(string name, Function func)
{
    FunctionMetadata metaData = FunctionMetadataRegistry.getFunctionByName(name);
    if (metaData == null)
    {
        if (AnalysisToolPak.isATPFunction(name))
        {
            throw new ArgumentException(name + " is a function from the Excel Analysis Toolpack. " + "Use AnalysisToolpack.registerFunction(String name, FreeRefFunction func) instead.");
        }
        throw new ArgumentException("Unknown function: " + name);
    }
    int idx = metaData.getIndex();
    if (functions[idx] is NotImplementedFunction)
    {
        functions[idx] = func;
    }
    else
    {
        throw new ArgumentException("POI already implememts " + name + ". You cannot override POI's implementations of Excel functions");
    }
}

public long Skip(long byteCount) {
    if (byteCount < 0) {
        throw new ArgumentException("byteCount < 0: " + byteCount);
    }
    lock (lock) {
        CheckNotClosed();
        if (byteCount < 1) {
            return 0;
        }
        if (end - pos >= byteCount) {
            pos += byteCount;
            return byteCount;
        }
        long read = end - pos;
        pos = end;
        while (read < byteCount) {
            if (FillBuf() == -1) {
                return read;
            }
            if (end - pos >= byteCount - read) {
                pos += byteCount - read;
                return byteCount;
            }
            read += (end - pos);
            pos = end;
        }
        return byteCount;
    }
}

public static readonly string HtmlEncode(string plainText)
{
    if (plainText == null || plainText.Length == 0)
    {
        return "";
    }
    StringBuilder result = new StringBuilder(plainText.Length);
    for (int index = 0; index < plainText.Length; index++)
    {
        char ch = plainText[index];
        switch (ch)
        {
            case '"':
                result.Append("&quot;");
                break;
            case '&':
                result.Append("&amp;");
                break;
            case '<':
                result.Append("&lt;");
                break;
            case '>':
                result.Append("&gt;");
                break;
            case '\'':
                result.Append("&#x27;");
                break;
            case '/':
                result.Append("&#x2F;");
                break;
            default:
                result.Append(ch);
                break;
        }
    }
    return result.ToString();
}

public ValueEval evaluate(int srcRowIndex, int srcColumnIndex, ValueEval numberVE)
{
    final String hex;
    if (numberVE instanceof RefEval)
    {
        RefEval re = (RefEval) numberVE;
        hex = OperandResolver.coerceValueToString(re.getInnerValueEval(re.getFirstSheetIndex()));
    }
    else
    {
        hex = OperandResolver.coerceValueToString(numberVE);
    }
    try
    {
        return new NumberEval(BaseNumberUtils.convertToDecimal(hex, HEXADECIMAL_BASE, MAX_NUMBER_OF_PLACES));
    }
    catch (IllegalArgumentException e)
    {
        return ErrorEval.NUM_ERROR;
    }
}

public string Validate(string uri, int start, int end, string name)
{
    for (int i = start; i < end; )
    {
        char ch = uri[i];
        if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || IsRetained(ch))
        {
            i++;
        }
        else if (ch == '%')
        {
            if (i + 2 >= end)
            {
                throw new UriFormatException("Incomplete % sequence in " + name);
            }
            int d1 = HexToInt(uri[i + 1]);
            int d2 = HexToInt(uri[i + 2]);
            if (d1 == -1 || d2 == -1)
            {
                throw new UriFormatException("Invalid % sequence: " + uri.Substring(i, 3) + " in " + name);
            }
            i += 3;
        }
        else
        {
            throw new UriFormatException("Illegal character in " + name);
        }
    }
    return uri.Substring(start, end - start);
}

public static QualityStats average(QualityStats[] stats) {
    QualityStats avg = new QualityStats(0,0);
    if (stats.Length==0) {
        return avg;
    }
    int m = 0;
    for (int i=0; i<stats.Length; i++) {
        avg.searchTime += stats[i].searchTime;
        avg.docNamesExtractTime += stats[i].docNamesExtractTime;
        if (stats[i].maxGoodPoints>0) {
            m++;
            avg.numGoodPoints += stats[i].numGoodPoints;
            avg.numPoints += stats[i].numPoints;
            avg.pReleventSum += stats[i].getAvp();
            avg.recall += stats[i].recall;
            avg.mrr += stats[i].getMRR();
            avg.maxGoodPoints += stats[i].maxGoodPoints;
            for (int j=1; j<avg.pAt.Length; j++) {
                avg.pAt[j] += stats[i].getPrecisionAt(j);
            }
        }
    }
    System.Diagnostics.Debug.Assert(m>0, "Fishy: no \"good\" queries!");
    avg.searchTime /= stats.Length;
    avg.docNamesExtractTime /= stats.Length;
    avg.numGoodPoints /= m;
    avg.numPoints /= m;
    avg.recall /= m;
    avg.mrr /= m;
    avg.maxGoodPoints /= m;
    for (int j=1; j<avg.pAt.Length; j++) {
        avg.pAt[j] /= m;
    }
    avg.pReleventSum /= m;
    avg.pReleventSum *= avg.maxGoodPoints;
    return avg;
}

public override string ToString()
{
    StringBuilder buffer = new StringBuilder();
    buffer.Append("[OBJECTLINK]\n");
    buffer.Append("    .anchorId             = ").Append("0x").Append(HexDump.ToHex(GetAnchorId())).Append(" (").Append(GetAnchorId()).Append(" )");
    buffer.Append(System.Environment.NewLine);
    buffer.Append("    .link1                = ").Append("0x").Append(HexDump.ToHex(GetLink1())).Append(" (").Append(GetLink1()).Append(" )");
    buffer.Append(System.Environment.NewLine);
    buffer.Append("    .link2                = ").Append("0x").Append(HexDump.ToHex(GetLink2())).Append(" (").Append(GetLink2()).Append(" )");
    buffer.Append(System.Environment.NewLine);
    buffer.Append("[/OBJECTLINK]\n");
    return buffer.ToString();
}
